from datetime import date, timedelta


class LeaveTracker:
    def __init__(
        self, days_per_year: int = 26, holidays: list[date] | None = None
    ) -> None:
        self.days_per_year = days_per_year
        self.holidays = set(holidays or [])
        self._used: dict[tuple[str, int], int] = {}

    def request(self, employee: str, start: date, end: date, today: date) -> int:
        """Request leave from start to end (inclusive); return leave days used."""
        if end < start:
            raise ValueError("End date cannot be before start date")
        if (start - today).days < 3:
            raise ValueError("Leave must be requested at least 3 days in advance")

        used_by_year: dict[int, int] = {}
        current = start
        while current <= end:
            if current.weekday() < 5 and current not in self.holidays:
                used_by_year[current.year] = used_by_year.get(current.year, 0) + 1
            if current == end:
                break
            current += timedelta(days=1)

        for year, days in used_by_year.items():
            key = (employee, year)
            self._used[key] = self._used.get(key, 0) + days

        return sum(used_by_year.values())

    def remaining(self, employee: str, year: int) -> int:
        return self.days_per_year - self._used.get((employee, year), 0)
